import queue


def accepted(cap: int, xs: list[int]) -> int:
    """Count how many elements from xs can be put into a bounded queue of capacity cap without blocking."""
    if cap <= 0:
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
            count += 1
        except queue.Full:
            break
    return count


def test_accepted_more_than_capacity() -> None:
    assert accepted(3, [10, 20, 30, 40, 50]) == 3


def test_accepted_fewer_than_capacity() -> None:
    assert accepted(5, [1, 2, 3]) == 3


def test_accepted_exact_capacity() -> None:
    assert accepted(4, [1, 2, 3, 4]) == 4


def test_accepted_empty_list() -> None:
    assert accepted(3, []) == 0


def test_accepted_zero_capacity() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_accepted_single_capacity() -> None:
    assert accepted(1, [42, 99]) == 1

